  "maj" => [0, 4, 7],
  "min" => [0, 3, 7],
  "7" => [0, 4, 7, 10],
  "maj7" => [0, 4, 7, 11],
  "m7" => [0, 3, 7, 10],
  "m9" => [0, 3, 7, 10, 2],
  "maj9" => [0, 4, 7, 11, 2],
  "sus" => [0, 5, 7],
  "dim" => [0, 3, 6],
  "7alt" => [0, 4, 7, 10, 1],
  "7#11" => [0, 4, 7, 10, 6],
  "m11" => [0, 3, 7, 10, 5],
  "sus4" => [0, 5, 7, 10],
  "aug" => [0, 4, 8],
  "6" => [0, 4, 7, 9],
